import { ONBOARDING_STYLE } from './private-onboarding-style.mjs'

const raw = value => typeof value === 'string' || typeof value === 'number' ? String(value) : ''
const html = value => raw(value).replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character]))
const list = value => Array.isArray(value) ? value : []
const count = value => Number.isSafeInteger(value) && value >= 0 ? value.toLocaleString('en-US') : '—'
const csrfInput = csrf => `<input type="hidden" name="csrf" value="${html(csrf)}">`
const LINKEDIN_EXPORT = 'https://www.linkedin.com/mypreferences/d/download-my-data'
const exportHelp = () => `<div class="export-help"><p class="small"><a href="${LINKEDIN_EXPORT}" target="_blank" rel="noopener noreferrer">Don't have your LinkedIn export yet? Request it now ↗</a></p><p class="small">It takes LinkedIn a few minutes for Connections, up to a day for the complete archive. Sign up while you wait.</p></div>`
const exportSteps = () => '<ol><li>Open LinkedIn’s data download settings on a personal computer.</li><li>Request the larger download for your full archive, or select Connections.</li><li>Download the email link within 72 hours and keep your file.</li></ol>'
// Keep native POSTs and their CSRF tokens on the current host.
const localAction = value => typeof value === 'string' && value.startsWith('/') && !value.startsWith('//') && !/[\\\s\x00-\x1f\x7f#]/.test(value) ? value : null
const profileLookup = ({ linkedinLookup, lookupResult, csrf }) => {
  const action = localAction(linkedinLookup?.action)
  const claimAction = lookupResult?.status === 'found' ? localAction(lookupResult.claimAction) : null
  return `${action ? `<form class="linkedin-lookup" method="post" action="${html(action)}">${csrfInput(csrf)}<label for="onboarding-linkedin-url">Find yourself on Unlinked <span class="small">Your LinkedIn address</span></label><input id="onboarding-linkedin-url" type="text" name="linkedinUrl" maxlength="2048" placeholder="linkedin.com/in/your-name" autocomplete="url" autocapitalize="off" spellcheck="false"><p class="small">Shows what Unlinked already knows about you: your old profile and members who list you. Nothing is claimed until you confirm.</p><button class="quiet" type="submit">Find me</button></form>` : ''}${claimAction ? `<div class="panel lookup-result"><h2>Is this you?</h2><h3>${html(lookupResult.profileName)}</h3><p>${html(lookupResult.headline)}</p><p>Listed by ${count(lookupResult.listedBy)} ${lookupResult.listedBy === 1 ? 'member' : 'members'}</p><form method="post" action="${html(claimAction)}">${csrfInput(csrf)}${lookupResult.claimToken ? `<input type="hidden" name="candidate" value="${html(lookupResult.claimToken)}">` : ''}<div class="actions"><button type="submit">Yes, that's me</button><a class="quiet" href="/profile">Not me</a></div></form></div>` : ''}`
}

// One search box, in the header of every page. A plain GET, so it works before
// sign-in, can be bookmarked and needs no script.
const headerSearch = ({ query, mode }) => `<form class="header-search" method="get" action="/network" role="search">${mode === 'exact' ? '<input type="hidden" name="mode" value="exact">' : ''}<svg class="search-icon" viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="7" cy="7" r="5"/><path d="m11 11 4 4"/></svg><input name="q" type="search" enterkeyhint="search" maxlength="200" aria-label="Search everyone on Unlinked" value="${html(query)}" placeholder="Search people, roles, companies"><button type="submit" aria-label="Search"><svg viewBox="0 0 20 20" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 10h12M11 5l5 5-5 5"/></svg></button></form>`
const steps = active => `<div class="steps" aria-label="Getting started">${['Account', 'Your LinkedIn export', 'Your profile'].map((name, index) => `<${active === index + 1 ? 'b aria-current="step"' : 'span'}>${index + 1}. ${name}</${active === index + 1 ? 'b' : 'span'}>`).join('<span aria-hidden="true">·</span>')}</div>`
const terminalJob = job => ['indexed', 'partial', 'failed'].includes(job?.status)
const jobLabel = job => job?.status === 'indexed' ? 'Import finished' : job?.status === 'partial' ? 'Import needs attention' : job?.status === 'failed' ? 'Import could not finish' : 'Importing…'
const jobProgress = job => Number.isSafeInteger(job?.total) && job.total > 0 && Number.isSafeInteger(job.processed) && job.processed >= 0 && job.processed <= job.total
  ? { processed: job.processed, total: job.total, percent: Math.round(job.processed / job.total * 100) } : null
const knownJob = job => job && ['uploaded', 'parsing', 'indexing', 'indexed', 'partial', 'failed'].includes(job.status)
const progress = job => { const value = jobProgress(job); return `<progress aria-label="Import in progress"${value ? ` value="${value.processed}" max="${value.total}"` : ''}></progress>` }
const jobStatus = job => {
  if (!knownJob(job)) return ''
  const finished = terminalJob(job)
  const value = jobProgress(job)
  const label = job.status === 'indexed' ? `Import finished · ${count(job.total)} records` : !finished && value ? `Importing · ${value.percent}% · ${count(value.processed)} of ${count(value.total)} records` : jobLabel(job)
  return `<aside class="import-status" role="status" aria-live="polite"><strong>${label}</strong>${!finished ? `${progress(job)}<p>Keeps running even if you leave this page.</p>${job.profileReady ? '<p>Your profile is ready; connections are still coming in.</p>' : ''}` : ''}${job.status === 'partial' ? '<p><a href="/settings">Review in Settings</a></p>' : ''}${job.errorMessage ? `<p>${html(job.errorMessage)}</p>` : ''}</aside>`
}
const jobPill = job => { if (!knownJob(job) || terminalJob(job)) return ''; const value = jobProgress(job); return `<a class="pill" href="/profile" title="Importing keeps running even if you leave">${value ? `Importing · ${value.percent}%` : 'Importing…'}</a>` }
const footer = ({ csrf, accountLabel }) => `<footer><span>unlinked · an open professional network</span><span><a href="https://www.unlinked.ai/meet" target="_blank" rel="noopener noreferrer">Meet someone in person ↗</a><a href="/agents">For agents</a><a href="/llms.txt">llms.txt</a></span><span>Not affiliated with LinkedIn.</span>${csrf ? `<span class="account">${accountLabel ? `Signed in as ${html(accountLabel)} · ` : ''}<form class="sign-out" method="post" action="/logout">${csrfInput(csrf)}<button class="link-button">Sign out</button></form></span>` : ''}</footer>`
// The account chip shows a name, never a full address or an opaque identifier.
const chipLabel = value => { const text = raw(value).trim(); return !text || /^[0-9a-f-]{20,}$/i.test(text) ? '' : text.includes('@') ? text.split('@')[0] : text }
const base = (title, content, { accountLabel, displayName, csrf, importJob, query = '', mode } = {}) => ({ title, content: `<style>${ONBOARDING_STYLE}</style><div class="unlinked-onboarding"><header><a class="logo" href="https://www.unlinked.ai/" aria-label="Unlinked home"><strong>unlinked</strong></a>${headerSearch({ query, mode })}<nav aria-label="Main navigation">${csrf ? `${jobPill(importJob)}<a href="/network">People</a><a href="/profile">My profile</a><a class="hide-m" href="/agents">For agents</a><a class="chip" href="/settings"${chipLabel(displayName) ? ' title="Settings"' : ''}>${chipLabel(displayName) ? html(chipLabel(displayName)) : 'Settings'}</a>` : '<a href="/people">Explore</a><a class="hide-m" href="/agents">For agents</a><a href="/login">Sign in</a><a class="button sm" href="/join">Join</a>'}</nav></header>${jobStatus(importJob)}<main class="journey">${content}</main>${footer({ csrf, accountLabel })}</div>` })

const HUES = ['#4349c4', '#2f6f8f', '#8a5a2b', '#6b4fa0', '#b0413e', '#3d6f7a']
const hue = seed => { let hash = 0; for (const character of raw(seed)) hash = (hash * 31 + character.codePointAt(0)) >>> 0; return HUES[hash % HUES.length] }
const initials = name => raw(name).trim().split(/\s+/).slice(0, 2).map(word => [...word][0] ?? '').join('')
// A given name reads well as a possessive; an initial such as “A.” does not.
const firstName = name => { const first = raw(name).trim().split(/\s+/)[0] ?? ''; return [...first].length > 2 && !first.endsWith('.') ? first : '' }
const avatar = (name, seed = name) => `<span class="initials avatar" style="background:${hue(seed)}" aria-hidden="true">${html(initials(name))}</span>`
const externalProfile = value => { try { const url = new URL(value); return url.protocol === 'https:' && ['linkedin.com', 'www.linkedin.com'].includes(url.hostname) && !url.username && !url.password ? url.href : null } catch { return null } }
const PRESENCE_FILTERS = [[undefined, 'All'], ['member', 'On Unlinked'], ['shadow', 'Not yet on Unlinked']]
const subline = value => [raw(value.headline), raw(value.company)].filter(Boolean).join(' · ')
// Imported people who have not joined. A network icon marks those connected to
// more than one person here, so their page leads somewhere; a dot marks a stub.
const NETWORK_ICON = '<svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="3.5" cy="8" r="2"/><circle cx="12.5" cy="3.5" r="2"/><circle cx="12.5" cy="12.5" r="2"/><path d="M5.3 7.1 10.7 4.4M5.3 8.9l5.4 2.7"/></svg>'
const STUB_ICON = '<svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="currentColor" stroke-width="1.6" stroke-dasharray="2.2 2" aria-hidden="true"><circle cx="8" cy="8" r="5.5"/></svg>'
const reach = value => Number.isSafeInteger(value?.connectionCount) && value.connectionCount > 1
const shadowBadge = (value, { withCount = true } = {}) => value?.presence !== 'shadow' ? '' : reach(value)
  ? `<span class="shadow net" title="Not on Unlinked yet. Imported profile connected to ${html(count(value.connectionCount))} people here.">${NETWORK_ICON}Imported${withCount ? ` · ${html(count(value.connectionCount))}` : ''}</span>`
  : `<span class="shadow" title="Not on Unlinked yet. Imported profile known through one connection.">${STUB_ICON}Imported</span>`
const personName = value => value.id ? `<a href="${memberHref(value)}">${html(value.name) || 'Unnamed connection'}</a>` : html(value.name) || 'Unnamed connection'
const person = value => `<article class="person">${avatar(value.name, value.id ?? value.name)}<div><h3>${personName(value)}${shadowBadge(value)}</h3><p>${html(subline(value))}</p>${externalProfile(value.linkedinUrl) ? `<a class="small" href="${html(externalProfile(value.linkedinUrl))}" target="_blank" rel="noopener noreferrer">LinkedIn profile ↗</a>` : ''}</div></article>`
const memberHref = value => html(`/people/${encodeURIComponent(raw(value.id))}`)
const member = value => `<article class="person">${avatar(value.name, value.id)}<div><h3><a href="${memberHref(value)}">${html(value.name)}</a>${shadowBadge(value)}</h3>${value.headline || value.company ? `<p>${html(subline(value))}</p>` : ''}${value.location ? `<p class="small">${html(value.location)}</p>` : ''}</div></article>`
const connectionRow = value => value.id
  ? `<a class="crow" href="${memberHref(value)}">${avatar(value.name, value.id)}<span><strong>${html(value.name)}</strong>${shadowBadge(value)}${subline(value) ? `<br><span class="small">${html(subline(value))}</span>` : ''}</span></a>`
  : `<div class="crow">${avatar(value.name)}<span><strong>${html(value.name) || 'Unnamed connection'}</strong>${subline(value) ? `<br><span class="small">${html(subline(value))}</span>` : ''}</span></div>`
const dates = value => [raw(value.startDate), raw(value.endDate)].filter(Boolean).join(' to ')
const companyLink = value => raw(value).trim() ? `<a href="${html(`/companies/${encodeURIComponent(raw(value).trim())}`)}">${html(value)}</a>` : ''
const experience = (positions, empty) => `<div class="card sec"><h3>Experience</h3>${list(positions).length ? list(positions).map(value => `<div class="xp"><b>${html(value.title)}</b>${companyLink(value.company)}${dates(value) ? `<br><span class="small">${html(dates(value))}</span>` : ''}${value.description ? `<p>${html(value.description)}</p>` : ''}</div>`).join('') : `<p class="small">${empty}</p>`}</div>`
const education = schools => list(schools).length ? `<div class="card sec"><h3>Education</h3>${list(schools).map(value => `<div class="xp"><b>${html(value.institution)}</b>${html(value.degree)}${dates(value) ? `<br><span class="small">${html(dates(value))}</span>` : ''}</div>`).join('')}</div>` : ''
const skills = values => list(values).length ? `<div class="card sec"><h3>Skills</h3><div class="tags">${list(values).map(value => `<span class="tag">${html(value)}</span>`).join('')}</div></div>` : ''
const sampleProfile = () => `<div class="card phead mini" aria-hidden="true"><div class="banner"></div><div class="pav">AL</div><h1>Avery Lee</h1><p class="hl">Director of Partnerships, Northwind Solar</p><span class="small">Oakland, California · 312 connections</span><div class="mini-sec"><b>Experience</b><p>Director of Partnerships · Northwind Solar<br><span class="small">2019 to now</span></p><p>Programme Manager · Open Orchard<br><span class="small">2015 to 2019</span></p></div><div class="mini-sec"><b>Connections</b><div class="faces"><span style="background:#2f6f8f">MS</span><span style="background:#6b4fa0">PB</span><span style="background:#8a5a2b">KN</span><span style="background:#b0413e">ZH</span><span class="moref">+308</span></div></div><p class="small" style="margin:14px 24px 0">Illustration with a fictional person.</p></div>`

// Signed-out home: what the product is, with search and profiles one click away.
export function renderLanding() {
  return base('Your professional profile and network', `<section class="land"><div><h1>Your professional profile and network, in a place that’s yours.</h1><p class="lead">Bring your profile and connections from LinkedIn. Explore who knows whom. Ask your AI agent who you need.</p><div class="cta"><a class="button lg" href="/join">Create my profile</a><a href="/people">or explore profiles first →</a></div><div class="drop"><strong>Start with your LinkedIn export</strong><p class="small">The complete archive ZIP from LinkedIn builds your whole profile. Connections.csv alone also works.</p><a class="button sec" href="/join">Bring my file</a><details><summary>Don’t have it yet? Get it from LinkedIn</summary>${exportSteps()}<p><a href="${LINKEDIN_EXPORT}" target="_blank" rel="noopener noreferrer">Open LinkedIn’s data download page ↗</a></p></details></div></div><div>${sampleProfile()}</div></section><section class="agentband"><div><b>Built for AI agents too.</b> Claude, ChatGPT or Cursor can search your people and everyone on Unlinked.</div><div><pre>https://www.unlinked.ai/mcp</pre><a href="/agents">How agents connect and what to upload →</a></div></section>`)
}

export function renderJoin({ signedIn = false, accountLabel, displayName, csrf, importJob } = {}) {
  return base('Join Unlinked', `<section class="narrow">${steps(1)}<h1 class="hq">Join Unlinked</h1><p class="lead">Bring the people you know into reach.</p><div class="sign-in-options"><a class="button" href="/login">Continue with Google</a><a class="button quiet" href="/login">Continue with email</a></div><p class="small">Same sign-in as OpenChat.</p>${!signedIn ? exportHelp() : ''}<p class="small">Already a member? <a href="/login">Sign in</a> · <a href="/people">Explore profiles first</a></p></section>`, signedIn ? { accountLabel, displayName, csrf, importJob } : {})
}

// A member page was opened without a session. Sign-in returns to that page.
export function renderSignInRequired({ next } = {}) {
  const target = localAction(next) ? `/login?next=${encodeURIComponent(next)}` : '/login'
  return base('Sign in to continue', `<section class="narrow"><h1 class="hq">Sign in to continue</h1><p class="lead">This page belongs to your account. Anyone can search and read profiles without signing in.</p><div class="sign-in-options"><a class="button" href="${html(target)}">Sign in</a><a class="button quiet" href="/join">Join Unlinked</a></div><p class="small"><a href="/people">Explore profiles</a></p></section>`)
}

export function renderBringArchive({ accountLabel, displayName, csrf, publicProfessionalSearch = false, limitBytes = 67108864, state = 'ready', errorMessage, syntheticMode = false, importJob }) {
  const size = Number.isSafeInteger(limitBytes) && limitBytes > 0 ? Math.floor(limitBytes / 1048576) : 64
  return base('Bring your LinkedIn export', `<section class="narrow">${steps(2)}<h1 class="hq">Bring your LinkedIn export</h1><p class="lead">Your full LinkedIn ZIP builds your profile and brings your connections. Connections-only ZIP or CSV also works.</p>${state === 'error' ? `<p class="notice error" role="alert">${html(errorMessage) || 'That file could not be imported. Try again, or choose Connections.csv from your archive.'}</p>` : ''}<form id="onboarding-upload" method="post" action="/upload" enctype="multipart/form-data">${csrfInput(csrf)}<label class="file">Choose your LinkedIn file<input required type="file" name="archive" accept=".zip,.csv"><span class="small">ZIP or CSV · up to ${size} MB</span></label>${syntheticMode ? '<label><input required type="checkbox" name="syntheticConsent" value="yes"> This is synthetic test data.</label>' : ''}<button id="onboarding-import" type="submit">Import my file</button><p class="small">${publicProfessionalSearch ? 'By importing, your profile and the people in your file can be found on Unlinked by members and visitors. Contact details and your original file stay private.' : 'By importing, your profile and connections join your Unlinked network, searchable by you and by any agent you connect. Contact details stay private.'}</p><section id="onboarding-progress" hidden role="status" aria-live="polite"><h2>Importing…</h2><progress aria-label="Importing your LinkedIn file"></progress><p>Uploading your file. Keep this page open until the upload finishes; the import then continues on the server.</p></section></form>${exportHelp()}<details><summary>Don’t have your export yet?</summary>${exportSteps()}</details><p><a href="/profile">Skip for now</a> · <a href="/network">Explore people</a></p></section>`, { accountLabel, displayName, csrf, importJob })
}

export function renderImporting({ accountLabel, displayName, csrf, importJob } = {}) {
  const finished = terminalJob(importJob)
  const message = importJob?.status === 'indexed' ? 'Your import is ready. Open People to search your connections.' : importJob?.status === 'partial' ? 'Your import did not finish completely. Review the import details in Settings.' : 'Your file could not be imported. Review the error above and try adding your file again.'
  const title = finished ? jobLabel(importJob) : 'Importing…'
  return base(title, `<section class="narrow">${steps(2)}<h1 class="hq">${title}</h1><div class="panel" role="status">${finished ? `<p>${message}</p><a href="${importJob.status === 'indexed' ? '/network' : '/settings'}">${importJob.status === 'indexed' ? 'Open People' : 'Open Settings'}</a>` : `<p>Reading your profile and connections.</p><p>Your profile is ready as soon as your file is read.</p><p>You can leave this page. The import keeps running.</p>${importJob?.profileReady ? '<a class="button" href="/profile">See your profile</a>' : ''}`}</div><p><a href="/network">Explore people while you wait</a></p></section>`, { accountLabel, displayName, csrf, importJob })
}

export function uploadProgressScript() {
  return `const form=document.getElementById('onboarding-upload');if(form){form.addEventListener('submit',()=>{if(!form.reportValidity())return;const button=document.getElementById('onboarding-import');button.disabled=true;button.textContent='Importing…';document.getElementById('onboarding-progress').hidden=false;});}`
}

// Install separately with the controller's CSP nonce; the textarea is usable without it.
export function agentSetupCopyScript() {
  return `const copyButton=document.getElementById('onboarding-copy-agent');const configuration=document.getElementById('onboarding-agent-configuration');const copyHelp=document.getElementById('onboarding-copy-help');if(copyButton&&configuration&&copyHelp){copyButton.addEventListener('click',async()=>{configuration.focus();configuration.select();try{await navigator.clipboard.writeText(configuration.value);copyHelp.textContent='Agent setup copied.';}catch{copyHelp.textContent='Setup selected. Copy it from the field above.';}});}`
}

export function renderOwnProfile({ accountLabel, displayName, csrf, publicProfessionalSearch = false, profile = {}, contacts = [], connectionCount, imports = [], importJob, linkedinLookup, lookupResult }) {
  const people = list(contacts), files = list(imports).length
  const total = Number.isSafeInteger(connectionCount) && connectionCount >= people.length ? connectionCount : people.length
  const facts = [raw(profile.location), total ? `${count(total)} ${total === 1 ? 'connection' : 'connections'}` : ''].filter(Boolean).join(' · ')
  return base("Here's your profile", `<section class="profile"><div><div class="card phead"><div class="banner"></div><div class="pav">${html(initials(profile.name)) || '·'}</div><h1>${html(profile.name) || 'Your profile'}</h1>${profile.headline ? `<p class="hl">${html(profile.headline)}</p>` : ''}${facts ? `<span class="small">${html(facts)}</span>` : ''}<div class="actions"><a class="button" href="/network">Looks good</a><a class="button sec" href="/card">My card</a><a class="button sec" href="/import">${files ? 'Add another file' : 'Bring my LinkedIn export'}</a><a class="button sec" href="/settings">Connect my agent</a></div><p class="notice">Built from your file. Fix anything later. <span class="small">Editing comes soon.</span></p></div>${profile.about ? `<div class="card sec"><h3>About</h3><p>${html(profile.about)}</p></div>` : ''}${experience(profile.positions, 'A full archive can include your experience.')}${education(profile.education)}${skills(profile.skills)}${profileLookup({ linkedinLookup, lookupResult, csrf })}</div><aside><div class="card sec"><h3>My connections${total ? ` · ${count(total)}` : ''}</h3>${people.length ? `${people.slice(0, 10).map(connectionRow).join('')}<p class="small"><a href="/network">See all the people you know →</a></p>` : '<p class="small">Bring your LinkedIn export to fill this in.</p><p><a href="/import">Add a file →</a></p>'}</div><p class="small">${files ? `${files} ${files === 1 ? 'file has' : 'files have'} been added to your account.` : 'You can add your file later.'} ${publicProfessionalSearch ? 'Contact details and your original file stay private.' : 'Your people remain private to your account.'}</p></aside></section>`, { accountLabel, displayName, csrf, importJob })
}

// The signed-in member's shareable business card: their public professional
// identity plus a QR code for it. `qr` is trusted server-rendered SVG markup
// built from the verified public profile URL; everything else is escaped.
// No contact details appear here — phone/email stay out until an explicit
// opt-in ships (see the separate phone-on-card work), and scanning the code
// only opens the same public profile page any visitor can read.
export function renderCard({ accountLabel, displayName, csrf, importJob, profile = {}, cardUrl, qr }) {
  const facts = [raw(profile.headline), raw(profile.location)].filter(Boolean).join(' · ')
  return base('My card', `<section class="narrow"><h1 class="hq">My card</h1><p class="lead">Show this code to someone you meet. Scanning it opens your public Unlinked profile — nothing more.</p><div class="card phead"><div class="banner"></div><div class="pav">${html(initials(profile.name)) || '·'}</div><h1>${html(profile.name) || 'Your card'}</h1>${facts ? `<p class="hl">${html(facts)}</p>` : ''}${cardUrl && qr ? `<div class="qr">${qr}</div><p class="small qr-url"><code>${html(cardUrl)}</code></p>` : '<p class="notice">Your QR code appears once your profile is published on Unlinked. Bring your LinkedIn export to publish it.</p>'}<div class="actions">${cardUrl ? `<a class="button sec sm" href="${html(cardUrl)}">Preview my public profile</a>` : '<a class="button sm" href="/import">Add my file</a>'}<a class="button sec sm" href="/meet">Scan someone’s card</a></div><p class="notice"><span class="small">Your card shows only what is already public: no phone number, email address or file contents.</span></p></div></section>`, { accountLabel, displayName, csrf, importJob })
}

// The early, optional find-yourself step: a LinkedIn address is a lookup hint,
// never proof of ownership or an import. Nothing is claimed without the
// explicit "Yes, that's me" confirmation, and skipping costs nothing.
// Someone you know who is not on Unlinked: kept with your own people, never
// published. LinkedIn's own export format needs both names and the profile URL.
export function renderAddPerson({ accountLabel, displayName, csrf, importJob, error, values = {} } = {}) {
  const field = (name, label, hint, required = false, type = 'text') => `<label>${label}${required ? '' : ' <span class="small">(optional)</span>'}<input name="${name}" type="${type}" maxlength="${type === 'url' ? 2048 : 120}"${required ? ' required' : ''} value="${html(values[name])}">${hint ? `<span class="small">${hint}</span>` : ''}</label>`
  return base('Add a person', `<section class="narrow"><h1 class="hq">Add a person</h1><p class="lead">Someone you know who is not on Unlinked. They join your own people, searchable by you and your agent. They are not published, and they are not told.</p>${error ? `<p class="notice error" role="alert">${html(error)}</p>` : ''}<form method="post" action="/people/add">${csrfInput(csrf)}${field('firstName', 'First name', '', true)}${field('lastName', 'Last name', '', true)}${field('linkedinUrl', 'LinkedIn profile', 'For example https://www.linkedin.com/in/their-name', true, 'url')}${field('company', 'Company')}${field('position', 'Role')}<button type="submit">Add to my people</button></form><p class="small"><a href="/invites">Invite someone to join instead →</a></p></section>`, { accountLabel, displayName, csrf, importJob })
}

const INVITATION_STATUS = { pending: 'Waiting', accepted: 'Accepted', declined: 'Declined', revoked: 'Revoked', expired: 'Expired' }
// Invites you send yourself: Unlinked never emails anyone.
export function renderInvites({ accountLabel, displayName, csrf, importJob, invitations = [], created, error, origin = 'https://www.unlinked.ai' } = {}) {
  const link = created ? `${raw(origin)}/i/${raw(created.token)}` : ''
  const fresh = created ? `<div class="card" role="status"><p><strong>Invite link for ${html(created.invitation.inviteeName)} is ready.</strong> Send this link yourself. It works once and expires in 14 days. It is shown only now.</p><label for="invite-link">Invite link</label><input id="invite-link" readonly value="${html(link)}"><p class="actions"><a class="button sec sm" href="${html(`mailto:?subject=${encodeURIComponent('Join me on Unlinked')}&body=${encodeURIComponent(`I'd like to connect on Unlinked: ${link}`)}`)}">Write an email</a></p></div>` : ''
  const rows = list(invitations).map(value => `<div class="row"><span>${html(value.inviteeName)}</span><b>${html(INVITATION_STATUS[value.status] ?? value.status)}</b>${value.status === 'pending' ? `<form method="post" action="/invites/revoke">${csrfInput(csrf)}<input type="hidden" name="id" value="${html(value.id)}"><button class="quiet sm">Revoke</button></form>` : ''}</div>`).join('')
  return base('Invite someone', `<section class="narrow wide"><h1 class="hq">Invite someone</h1><p class="lead">Invite someone who is not on Unlinked yet. You get a link to send them yourself.</p>${error ? `<p class="notice error" role="alert">${html(error)}</p>` : ''}${fresh}<form method="post" action="/invites">${csrfInput(csrf)}<label>Their name<input name="inviteeName" required maxlength="120"></label><button type="submit">Create invite link</button></form><h2>Your invites</h2><div class="card">${rows || '<p class="small">No invites yet.</p>'}</div><p class="small">Accepting an invite only tells you they joined. It never links them to a profile on its own. <a href="/people/add">Add someone to your people instead →</a></p></section>`, { accountLabel, displayName, csrf, importJob })
}

// The page an invite link opens, signed in or not.
export function renderInviteLanding({ accountLabel, displayName, csrf, token, invitation, outcome } = {}) {
  const valid = invitation?.status === 'pending'
  const path = `/i/${raw(token)}`
  const body = outcome === 'accepted' ? `<p class="lead">You accepted ${html(invitation.inviterName)}'s invite.</p><p><a class="button" href="/profile">Continue to your profile</a></p>`
    : outcome === 'declined' ? '<p class="lead">You declined the invite. Nothing was linked to your account.</p>'
    : invitation?.status === 'own' ? '<p class="lead">This is your own invite. Send the link to the person you invited.</p><p><a href="/invites">Your invitations</a></p>'
    : !valid ? `<p class="lead">This invite ${invitation?.status === 'expired' ? 'has expired' : 'is no longer available'}.</p><p><a href="/">Learn about Unlinked</a></p>`
    : `<p class="lead">${html(invitation.inviterName)} invited ${html(invitation.inviteeName)} to Unlinked, an open professional network.</p>${csrf
      ? `<form method="post" action="${html(path)}">${csrfInput(csrf)}<p class="small">Signed in as ${html(accountLabel)}. Accepting tells ${html(invitation.inviterName)} you joined; it does not link you to any profile.</p><div class="actions"><button name="action" value="accept">Accept</button><button class="quiet" name="action" value="decline">Decline</button></div></form>`
      : `<div class="actions"><a class="button" href="${html(`/login?next=${encodeURIComponent(path)}`)}">Sign in or join to accept</a></div><p class="small">Unlinked asks you to confirm after you sign in.</p>`}`
  return base('Invite', `<section class="narrow"><h1 class="hq">You're invited</h1>${body}</section>`, { accountLabel, displayName, csrf })
}

export function renderFindMe({ accountLabel, displayName, csrf, importJob, lookupResult, notice } = {}) {
  return base('Were you already on Unlinked?', `<section class="narrow"><h1 class="hq">Were you already on Unlinked?</h1><p class="lead">Thousands of profiles carried over from the original Unlinked. If yours is here, you can claim it — or skip and build a fresh one from your export.</p>${notice ? `<p class="notice">${html(notice)}</p>` : ''}${profileLookup({ linkedinLookup: { action: '/find-me' }, lookupResult, csrf })}${lookupResult?.status === 'none' ? '<p class="notice">Nothing unclaimed matched. You can continue — your LinkedIn export builds your profile either way.</p>' : ''}<p class="small"><a href="/">Skip for now →</a></p></section>`, { accountLabel, displayName, csrf, importJob })
}

// Anyone's profile, readable with or without a session: who they are and who they know.
export function renderPerson({ accountLabel, displayName, csrf, importJob, profile = {} } = {}) {
  const connections = list(profile.connections), id = raw(profile.id), tone = hue(id || profile.name)
  const more = typeof profile.nextConnectionsCursor === 'string' && profile.nextConnectionsCursor ? `/people/${encodeURIComponent(id)}?cursor=${encodeURIComponent(profile.nextConnectionsCursor)}` : null
  const total = Number.isSafeInteger(profile.connectionCount) ? profile.connectionCount : null
  const known = total ? `${count(total)} ${total === 1 ? 'connection' : 'connections'}` : connections.length ? `${count(connections.length)}${more ? '+' : ''} ${connections.length === 1 && !more ? 'connection' : 'connections'}` : ''
  const shadowNote = profile.presence === 'shadow' ? `<p class="small shadow-note">${shadowBadge(profile, { withCount: false })} Not on Unlinked yet. This profile was imported from LinkedIn connections. Is this you? <a href="${csrf ? '/find-me' : '/join'}">Claim it</a></p>` : ''
  const facts = [raw(profile.location), known].filter(Boolean).join(' · ')
  const owner = firstName(profile.name)
  return base(raw(profile.name) || 'Profile', `<section class="profile"><div><div class="card phead"><div class="banner" style="--h:${tone}"></div><div class="pav" style="--h:${tone}">${html(initials(profile.name))}</div><h1>${html(profile.name)}</h1>${profile.headline ? `<p class="hl">${html(profile.headline)}</p>` : ''}${facts ? `<span class="small">${html(facts)}</span>` : ''}${shadowNote}<div class="actions">${csrf ? '' : '<a class="button sm" href="/join">Join Unlinked</a>'}<a class="button sec sm" href="${csrf ? '/network' : '/people'}">Search everyone</a></div></div>${profile.about ? `<div class="card sec"><h3>About</h3><p>${html(profile.about)}</p></div>` : ''}${experience(profile.positions, 'Not listed.')}${education(profile.education)}${skills(profile.skills)}</div><aside><div class="card sec"><h3>${owner ? `${html(owner)}’s connections` : 'Connections'}${total ? ` · ${count(total)}` : connections.length ? ` · ${count(connections.length)}${more ? '+' : ''}` : ''}</h3>${connections.length ? connections.map(connectionRow).join('') : '<p class="small">None listed yet.</p>'}${more ? `<p><a href="${html(more)}">Show more</a></p>` : ''}</div></aside></section>`, { accountLabel, displayName, csrf, importJob })
}

// A company page, readable with or without a session: reviewed facts when we
// have them, and everyone on Unlinked whose profile ties them to the company.
export function renderCompany({ accountLabel, displayName, csrf, importJob, name, facts = null, people = [], total = 0, nextCursor } = {}) {
  const title = raw(facts?.name).trim() || raw(name).trim()
  const tone = hue(title)
  const factLine = [raw(facts?.industry), facts?.employeeCount ? `${count(facts.employeeCount)} employees on LinkedIn` : '', raw(facts?.headquarters), facts?.founded ? `Founded ${raw(facts.founded)}` : ''].filter(Boolean).join(' · ')
  const rows = list(people)
  const more = typeof nextCursor === 'string' && nextCursor ? `/companies/${encodeURIComponent(raw(name).trim())}?cursor=${encodeURIComponent(nextCursor)}` : null
  return base(title || 'Company', `<section class="profile"><div><div class="card phead"><div class="banner" style="--h:${tone}"></div><div class="pav" style="--h:${tone}">${html(initials(title))}</div><h1>${html(title)}</h1>${facts?.tagline ? `<p class="hl">${html(facts.tagline)}</p>` : ''}${factLine ? `<span class="small">${html(factLine)}</span>` : ''}<div class="actions">${csrf ? '' : '<a class="button sm" href="/join">Join Unlinked</a>'}<a class="button sec sm" href="${csrf ? '/network' : '/people'}">Search everyone</a></div></div>${facts?.description ? `<div class="card sec"><h3>About</h3><p>${html(facts.description)}</p></div>` : ''}${facts?.linkedinUrl && externalCompany(facts.linkedinUrl) ? `<p class="small"><a href="${html(externalCompany(facts.linkedinUrl))}" target="_blank" rel="noopener noreferrer">LinkedIn page ↗</a></p>` : ''}</div><aside><div class="card sec"><h3>On Unlinked${total ? ` · ${count(total)}` : ''}</h3>${rows.length ? rows.map(connectionRow).join('') : '<p class="small">No one on Unlinked lists this company yet.</p>'}${more ? `<p><a href="${html(more)}">Show more</a></p>` : ''}</div></aside></section>`, { accountLabel, displayName, csrf, importJob })
}
const externalCompany = value => { try { const url = new URL(raw(value)); return url.protocol === 'https:' && ['linkedin.com', 'www.linkedin.com'].includes(url.hostname) && !url.username && !url.password ? url.href : null } catch { return null } }

export function renderPeople({ accountLabel, displayName, csrf, query = '', mode = 'best', presence, added = false, match, everyone, own, contacts, searchResults, aiMatches, aiNote, aiError, anonymousAi = false, nextCursor, state = 'ready', importJob, publicProfessionalSearch }) {
  const exact = mode === 'exact', kept = presence === 'member' || presence === 'shadow' ? presence : undefined
  const searched = `q=${encodeURIComponent(raw(query))}${kept ? `&presence=${kept}` : ''}`
  // Two ways to read the same words: forgiving by default, literal on request.
  const modes = raw(query) ? `<p class="small modes">${exact ? `<a href="${html(`/network?${searched}`)}">Best match</a> · <b aria-current="true">Exact words</b>` : `<b aria-current="true">Best match</b> · <a href="${html(`/network?${searched}&mode=exact`)}">Exact words</a>`} · <a href="${kept ? `/network?presence=${kept}` : '/network'}">Clear search</a></p>${!exact && match === 'some' ? '<p class="notice">No one has every word. Showing people who match some of them.</p>' : ''}` : ''
  const legacy = own === undefined && (contacts !== undefined || searchResults !== undefined)
  const canSearchEveryone = publicProfessionalSearch ?? (everyone !== undefined || legacy)
  if (legacy) own = list(searchResults !== undefined ? searchResults : contacts)
  const noMatch = query && (!legacy || list(contacts).length > 0)
  const ownGroup = own === undefined ? '' : `<section class="own-group" aria-label="People you know"><h2>People you know</h2>${list(own).length ? `<div class="panel list">${list(own).map(value => `${person(value)}${value.reason ? `<p class="reason">${html(value.reason)}</p>` : ''}`).join('')}</div>` : `<div class="notice">${noMatch ? 'No people matched. Try another name or company.' : 'Bring your LinkedIn export to see your people.'} <a href="/import">Add a file →</a></div>`}</section>`
  // Who to show: everyone, people who joined, or imported profiles not on Unlinked yet.
  const filterHref = value => `/network${[raw(query) ? `q=${encodeURIComponent(raw(query))}` : '', exact ? 'mode=exact' : '', value ? `presence=${value}` : ''].filter(Boolean).reduce((path, part, index) => `${path}${index ? '&' : '?'}${part}`, '')}`
  const presenceFilter = `<p class="small modes presence" role="navigation" aria-label="Who to show">${PRESENCE_FILTERS.map(([value, label]) => value === kept ? `<b aria-current="true">${label}</b>` : `<a href="${html(filterHref(value))}">${label}</a>`).join(' · ')}</p>`
  const everyoneTitle = kept === 'member' ? 'On Unlinked' : kept === 'shadow' ? 'Not yet on Unlinked' : 'Everyone on Unlinked'
  const emptyEveryone = kept === 'member' ? `${query ? 'No one who joined matches that yet.' : 'No one has joined yet.'} Most profiles here were imported from LinkedIn connections.` : query ? 'No one on Unlinked matched that yet.' : 'No members to show yet.'
  const everyoneGroup = everyone === undefined ? '' : `<section class="everyone-group" aria-label="${everyoneTitle}"><h2>${everyoneTitle}</h2>${presenceFilter}${state === 'unavailable' ? '<p class="notice">Member search is on its way.</p>' : list(everyone).length ? `<div class="panel list">${list(everyone).map(member).join('')}</div>` : `<p class="notice">${emptyEveryone}</p>`}</section>`
  const more = typeof nextCursor === 'string' && nextCursor ? `<p><a class="button sec sm" href="${html(`/network?${raw(query) ? `${searched}&` : kept ? `presence=${kept}&` : ''}${exact ? 'mode=exact&' : ''}cursor=${encodeURIComponent(nextCursor)}`)}">Show more</a></p>` : ''
  // The same words, ranked by AI. A button on the results, not a second search box.
  const scopes = csrf && raw(query) ? [canSearchEveryone ? ['everyone', 'everyone'] : null, own !== undefined ? ['own', 'my people'] : null].filter(Boolean) : []
  // A visitor gets the same AI ranking over the public list; it carries no session authority.
  const askAi = scopes.length ? `<form class="ask-ai actions" method="post" action="/search-account">${csrfInput(csrf)}<input type="hidden" name="query" value="${html(query)}"><span class="small">Looking for something less literal?</span>${scopes.map(([value, label]) => `<button class="quiet sm" type="submit" name="scope" value="${value}">Ask AI across ${label}</button>`).join('')}</form>`
    : !csrf && anonymousAi && raw(query) ? `<form class="ask-ai actions" method="post" action="/ask"><input type="hidden" name="query" value="${html(query)}"><span class="small">Looking for something less literal?</span><button class="quiet sm" type="submit">Ask AI</button></form>` : ''
  // AI picks carry the model's reason; plain list rows never do.
  const aiGroup = aiMatches === undefined && !aiError ? '' : aiError ? `<section class="ai-group" aria-label="AI picks"><h2>AI picks</h2><p class="notice error" role="alert">${html(aiError)}</p></section>` : `<section class="ai-group" aria-label="AI picks"><h2>AI picks</h2>${list(aiMatches).length ? `<div class="panel list">${list(aiMatches).map(value => `${member(value)}${value.reason ? `<p class="reason">${html(value.reason)}</p>` : ''}`).join('')}</div>` : '<p class="notice">The AI found no one who fits. Try other words.</p>'}<p class="small">${aiNote ? `${html(aiNote)} ` : ''}OpenAI received your words and a limited set of public names, headlines and roles.</p></section>`
  return base('People', `<section class="dir"><h1 class="hq">${raw(query) ? `Results for “${html(query)}”` : 'People'}</h1>${modes}${raw(query) ? '' : `<p class="lead">${state === 'welcome' ? "You're in. " : ''}${own === undefined ? 'People on Unlinked, ready to search.' : 'The people you know, ready to search.'}</p>`}${added ? '<p class="notice" role="status">Added to your people. They appear here once processed, usually within a minute.</p>' : ''}${askAi}${state === 'error' ? '<p class="notice error" role="alert">We could not read your people right now. Try again; this does not mean your network is empty.</p>' : `${aiGroup}${ownGroup}${everyoneGroup}${more}`}<p class="small">${csrf ? '<a href="/people/add">Add a person</a> · <a href="/invites">Invite someone</a> · ' : ''}Friends come soon.</p></section>`, { accountLabel, displayName, csrf, importJob, query, mode })
}

export function renderSettings({ accountLabel, displayName, csrf, publicProfessionalSearch = false, imports = [], grants = [], agentConfiguration, agentSetupAutomatic = false, importJob, deleteError }) {
  const serialized = typeof agentConfiguration === 'string' ? agentConfiguration : agentConfiguration ? JSON.stringify(agentConfiguration, null, 2) : null
  return base('Settings', `<section class="narrow wide"><h1 class="hq">Settings</h1><h2>Your account</h2><div class="card"><p>Signed in as <b>${html(accountLabel)}</b>.</p><form method="post" action="/logout">${csrfInput(csrf)}<button class="quiet" type="submit">Sign out</button></form><p class="small">Signing out ends this session on this device. Your profile, files and agent access stay.</p></div><h2>Your agent</h2><div class="card"><p>${serialized && agentSetupAutomatic ? 'Your agent setup is ready — nothing to create. It searches your current and future files until you revoke access.' : 'Search your current and future files until you revoke access.'}</p>${serialized ? `<label for="onboarding-agent-configuration">Agent configuration</label><textarea id="onboarding-agent-configuration" readonly rows="8">${html(serialized)}</textarea><button id="onboarding-copy-agent" type="button" class="quiet" aria-describedby="onboarding-copy-help">Copy agent setup</button><p id="onboarding-copy-help" class="small" role="status">You can also select and copy the setup above.</p><p class="small">Keep this credential private. A real search call confirms your client is connected.</p>` : agentSetupAutomatic ? '<p class="notice">Agent access is revoked. Regenerate a setup below when you want to reconnect an agent.</p>' : ''}<form method="post" action="/setup-account">${csrfInput(csrf)}<button>${serialized ? 'Regenerate agent setup' : 'Create agent setup'}</button>${serialized ? '<p class="small">Regenerating revokes this setup and issues a new credential; a copied old setup stops working.</p>' : ''}</form>${list(grants).map(value => `<form method="post" action="/revoke-account">${csrfInput(csrf)}<input type="hidden" name="grantId" value="${html(value.id)}"><p>Active agent access</p><button class="quiet">Revoke access</button></form>`).join('')}<p class="small"><a href="/agents">How agents connect and what to upload</a></p></div><h2>Privacy</h2><div class="card"><p>${publicProfessionalSearch ? 'Your original file and contact details stay private. New imports make professional profiles and connections findable by members and visitors; earlier private imports remain private.' : 'Your file, profile and connections stay private to your account.'} When you or an agent you connect searches, OpenAI receives the search query and a limited set of relevant names, companies, roles and connection dates. Contact email addresses and phone numbers are never sent.</p></div><h2>Your files</h2><div class="card">${list(imports).map(value => `<details><summary>${html(value.filename)} · import details</summary><p>${count(value.accepted)} records accepted · ${count(value.indexed)} indexed.</p><p>${html(value.status)}</p><p>Professional profiles and connections: ${value.visibility === 'public' ? 'public' : 'private'}.</p>${value.sha256 ? `<p>SHA-256: <code>${html(value.sha256)}</code></p>` : ''}${/^[a-zA-Z0-9_-]+$/.test(raw(value.id)) ? `<a href="/imports/${encodeURIComponent(raw(value.id))}">View technical details</a>` : ''}</details>`).join('') || '<p>No files added yet.</p>'}<p><a href="/import">Add a file →</a></p></div><h2>Your data</h2><div class="card"><p>Your profile, connections and files belong to you. Take a full copy, or erase everything, whenever you want.</p><form method="get" action="/export"><button class="quiet" type="submit">Download everything (JSON)</button></form><p class="small">One file with your profile, every import and the people in it, recovered legacy records, and your agent grants.</p><details${deleteError ? ' open' : ''}><summary>Delete everything…</summary><p>This permanently erases your imports, profile, connections, receipts and agent access, and removes you from the public People index. There is no undo. You can sign in again later, but you start from nothing.</p>${deleteError ? `<p class="notice error" role="alert">${html(deleteError)}</p>` : ''}<form method="post" action="/delete-account">${csrfInput(csrf)}<label for="delete-confirm">Type <b>delete everything</b> to confirm</label><input id="delete-confirm" type="text" name="confirm" autocomplete="off" autocapitalize="off" spellcheck="false" required placeholder="delete everything"><button class="danger" type="submit">Permanently delete my data</button></form></details></div></section>`, { accountLabel, displayName, csrf, importJob })
}

// Shown once, right after an account's data has been erased. No session remains.
export function renderDataDeleted() {
  return base('Your data is deleted', `<section class="narrow"><h1 class="hq">Your data is deleted</h1><p class="lead">Your imports, profile, connections and agent access have been erased, and you no longer appear in the public People index.</p><p>If you ever want to come back, sign in again and bring a fresh LinkedIn export.</p><p><a class="button" href="/">Back to the home page</a></p></section>`)
}

// Public guides, readable with or without a session.
export function renderAgents({ accountLabel, displayName, csrf, importJob } = {}) {
  return base('Unlinked for AI agents', `<section class="narrow wide"><h1 class="hq">Unlinked for AI agents</h1><p class="lead">Unlinked is meant to be used by agents as much as by people. An agent you connect can search your people and everyone on Unlinked.</p><div class="card sec"><h3>1. Connect</h3><pre>https://www.unlinked.ai/mcp</pre><p>Sign in and open Settings — your agent setup is prepared automatically and ready to copy. Paste the configuration into an MCP client that supports Streamable HTTP and bearer headers.</p><p class="small">Your account-scoped grant searches your current and future imported network and the published professional People index until you revoke it in Settings, where you can also regenerate a fresh credential. Everyone browsing needs no sign-in or archive. The grant excludes raw archives and contact details. Keep the configuration private.</p><div class="actions">${csrf ? '<a class="button sm" href="/settings">Open Settings</a>' : '<a class="button sm" href="/login?next=%2Fsettings">Sign in for your agent setup</a>'}</div></div><div class="card sec"><h3>2. What to upload, and how</h3>${exportSteps()}<div class="row"><span>Read from the archive</span><b>Connections, Profile, Positions, Education, Skills</b></div><div class="row"><span>Also accepted</span><b>Connections.csv on its own</b></div><p class="small"><a href="/import-linkedin">Import instructions</a> · <a href="${LINKEDIN_EXPORT}" target="_blank" rel="noopener noreferrer">Request your LinkedIn export ↗</a></p></div><div class="card sec"><h3>3. What an agent can do</h3><div class="row"><span><code>unlinked_search_network</code></span><b>Search the person’s own connections</b></div><div class="row"><span><code>unlinked_search_everyone</code></span><b>Search every published profile on Unlinked</b></div><div class="row"><span>Send messages or post anywhere</span><b>Never</b></div></div><div class="card sec"><h3>4. Machine-readable</h3><p>The same instructions are at <a href="/llms.txt">Agent guide</a>, with the interface at <a href="/openapi.json">API description</a> and <a href="/.well-known/mcp/server-card.json">the MCP server card</a>.</p></div></section>`, { accountLabel, displayName, csrf, importJob })
}

export function renderImportGuide({ accountLabel, displayName, csrf, importJob } = {}) {
  return base('Bring your LinkedIn export', `<section class="narrow wide"><h1 class="hq">Bring your LinkedIn export</h1><p class="lead">Request your LinkedIn data export on the LinkedIn website, then import the ZIP after signing in.</p><div class="card sec"><h3>What to request</h3><p>A complete archive can include your profile, experience, education, skills and connections. Connections-only ZIP or CSV is also supported.</p>${exportSteps()}<p><a href="${LINKEDIN_EXPORT}" target="_blank" rel="noopener noreferrer">Request LinkedIn export ↗</a></p></div><div class="card sec"><h3>What happens next</h3><p>Maximum archive size: 64 MiB. Processing continues on the server after you leave the page; return to Profile or People for progress. Search and agent setup use your own account’s published records.</p><div class="actions">${csrf ? '<a class="button sm" href="/import">Import my file</a>' : '<a class="button sm" href="/login?next=%2Fimport">Sign in and import</a>'}<a class="button sec sm" href="${csrf ? '/network' : '/people'}">Explore people</a></div></div></section>`, { accountLabel, displayName, csrf, importJob })
}

// The controls keep their ids; the controller attaches the scanner script with its own nonce.
// Nothing opens, and no contact or access changes, until the person presses Open.
export function renderMeet({ accountLabel, displayName, csrf, importJob } = {}) {
  return base('Meet someone', `<section class="narrow wide"><h1 class="hq">Meet someone</h1><p class="lead">Scan an Unlinked profile card or an OpenChat card, or paste its link. You confirm what was scanned before anything opens; scanning never adds a contact or grants access by itself.</p><div class="card"><div class="actions"><button id="start" type="button">Scan a card</button><button id="stop" type="button" class="quiet">Stop camera</button></div><div id="camera"></div><div id="confirm" class="notice" hidden><p>Scanned: <b id="confirm-label"></b></p><p class="small">Open it to continue. Opening a profile only shows its public page.</p><div class="actions"><a id="confirm-open" class="button sm" href="/meet">Open</a><button id="confirm-cancel" type="button" class="quiet sm">Cancel</button></div></div><form id="paste"><label for="card-url">Card or profile link</label><input id="card-url" type="text" inputmode="url" required><div class="actions"><button class="quiet">Check link</button></div></form><p id="status" class="small" role="status"></p></div><p class="small">If the camera is unavailable or permission is declined, paste the link printed with the card instead.</p></section>`, { accountLabel, displayName, csrf, importJob })
}
